/**
 * ROOT — Registers all compositions with Remotion.
 *
 * Compositions are auto-discovered from src/scenes/.
 * DO NOT EDIT this file when adding scenes.
 */

import React from "react";
import { Composition } from "remotion";
import { VIDEO } from "./design/tokens";
import { Video } from "./Video";
import { scenes } from "./scenes";

const FPS = VIDEO.fps;

export const RemotionRoot: React.FC = () => {
  const totalDurationInFrames = scenes.reduce(
    (sum, s) => sum + Math.round(s.config.durationInSeconds * FPS),
    0
  );

  return (
    <>
      {/* Full video — all scenes composed in order */}
      {totalDurationInFrames > 0 && (
        <Composition
          id="MainVideo"
          component={Video}
          durationInFrames={totalDurationInFrames}
          fps={FPS}
          width={VIDEO.width}
          height={VIDEO.height}
        />
      )}

      {/* Individual scene compositions — for isolated preview/render */}
      {scenes.map((scene) => (
        <Composition
          key={scene.config.id}
          id={scene.config.id}
          component={scene.Component}
          durationInFrames={Math.round(scene.config.durationInSeconds * FPS)}
          fps={FPS}
          width={VIDEO.width}
          height={VIDEO.height}
        />
      ))}
    </>
  );
};
